"""Standalone browser report for direct AI decisions and semantic extrapolation."""
from __future__ import annotations

import json
from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd


def report(out):
    out = Path(out)
    scores = pd.read_parquet(out / "news_risk_scores.parquet")
    summary = json.loads((out / "summary.json").read_text())
    audit = json.loads((out / "frozen_ai_audit.json").read_text())
    figures = out / "figures"
    figures.mkdir(exist_ok=True)
    plt.style.use("seaborn-v0_8-whitegrid")
    fig, axs = plt.subplots(1, 2, figsize=(12, 4), constrained_layout=True)
    axs[0].hist(scores.danger_score, bins=np.arange(0, 105, 5), color="#137c75", edgecolor="white")
    axs[0].set(xlabel="Remaining-danger rubric index (not probability)", ylabel="Articles", xlim=(0,100))
    axs[1].scatter(scores['N']*4, scores['T']*4, c=scores.danger_score, s=7, alpha=.35, cmap="magma", vmin=0, vmax=100)
    axs[1].set(xlabel="Negativity N (0-4)", ylabel="Remaining threat T (0-4)", xlim=(-.1,4.1), ylim=(-.1,4.1))
    for suffix in ["png", "svg"]:
        fig.savefig(figures / ("risk_distribution."+suffix), dpi=160)
    plt.close(fig)
    fig, ax=plt.subplots(figsize=(8,4),constrained_layout=True)
    for name,key in [('48 stratified AI audit articles','rounds'),('16 targeted AI stress articles','targeted_challenge_rounds')]:
        ax.plot([r['round'] for r in audit[key]],[r['danger_index_mae_0_to_100'] for r in audit[key]],marker='o',label=name)
    ax.set(xlabel='Frozen model round',ylabel='MAE against same-session AI rubric (0-100)',xticks=[1,2,3])
    ax.legend()
    for suffix in ['png','svg']:fig.savefig(figures/('audit_rounds.'+suffix),dpi=160)
    plt.close(fig)
    cols = ["news_id", "title", "summary", "source", "url", "published_date", "body_sha256", "assessment_body_sha256", "input_correction", "assessment_research_eligible", "split", "N", "T", "A", "S", "L", "I", "X", "danger_score", "model_danger_score", "danger_band", "bootstrap_p10", "bootstrap_p90", "rubric_sensitivity_min", "rubric_sensitivity_max", "nearest_development_news_id", "nearest_title_similarity", "score_source", "session_reviewed", "decision_state", "rationale", "requires_further_ai_review"]
    data = {"summary":summary, "audit":audit, "articles": scores[cols].to_dict("records")}
    payload = json.dumps(data, ensure_ascii=False, allow_nan=False).replace("<", "\\u003c").replace("&", "\\u0026")
    html = r'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>News2Neuron · 뉴스 위험성 평가</title><style>
:root{--ink:#152a2c;--muted:#516365;--paper:#f4f6f3;--accent:#126b64;--line:#d5dfd9}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--paper);font:15px/1.65 system-ui,sans-serif}header{background:#122d30;color:#eff6ed;padding:44px max(5vw,18px)}.eyebrow{font-size:12px;letter-spacing:.13em;color:#8fd6b8}h1{font-size:clamp(28px,4vw,48px);line-height:1.2;margin:15px 0}header p{max-width:950px;color:#c2d8d1}.tag{display:inline-block;font-size:12px;border:1px solid #729a8c;border-radius:20px;padding:3px 12px;margin-right:5px}main{max-width:1450px;margin:auto;padding:24px max(3vw,16px)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card,section{background:white;border:1px solid var(--line);border-radius:12px;padding:20px;margin-bottom:20px}.metric{font-size:30px;font-weight:700}.muted,small{color:var(--muted)}h2{font-size:21px;margin:0 0 12px}.controls{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}input,select,button{font:inherit;border:1px solid #c0d0c6;border-radius:7px;padding:8px 12px;background:white;color:var(--ink)}input[type=search]{flex:1;min-width:180px}button{cursor:pointer}button:hover{background:#d7eae1}button:disabled{opacity:.4;cursor:default}a{color:var(--accent)}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:740px}th,td{border-bottom:1px solid #e3e9e4;padding:12px 10px;text-align:left;font-size:13px}th{color:var(--muted);white-space:nowrap}td:first-child{max-width:470px}td button{text-align:left;border:0;padding:0;background:transparent;font-size:14px;line-height:1.5}.score{font-variant-numeric:tabular-nums;font-size:19px;font-weight:700}.pill{padding:3px 8px;border-radius:9px;font-size:12px;background:#edf3ef;white-space:nowrap}.direct{background:#d8eddf}.high{background:#fae0cf}.critical{background:#f4cfcd}.moderate{background:#f8edd0}.row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.chart{width:100%;height:auto}details{margin-top:12px}summary{cursor:pointer;font-weight:600}.note{border-left:4px solid #d8a459;padding-left:16px;color:#4f5144}dialog{max-width:820px;width:94vw;border:1px solid var(--line);border-radius:14px;padding:25px;max-height:90vh;overflow:auto}dialog::backdrop{background:#0d272ca1}.axes{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:18px 0}.axis{background:var(--paper);padding:12px;border-radius:8px}.axis b{display:block;font-size:23px}.downloads{display:flex;gap:20px;flex-wrap:wrap}.audit th,.audit td{text-align:center}.audit{min-width:500px}.stamp{font-size:12px;color:#a6c5b8}footer{font-size:12px;color:var(--muted);padding-bottom:25px}@media(max-width:700px){.metrics,.axes{grid-template-columns:repeat(2,1fr)}header{padding:28px 18px}section,.card{padding:15px}main{padding:16px}.metric{font-size:24px}}
</style><header><div class="eyebrow">NEWS2NEURON / ARTICLE RISK LAB</div><h1>뉴스가 전하는 위해를<br>숫자와 근거로 살펴봅니다.</h1><p>기사가 제시하는 피해와 남은 위험을 분리했습니다. 전체 본문의 의미를 처리한 예측에 직접 AI 판정을 더하고, 세 차례의 보정 결과를 기록했습니다.</p><span class="tag">한국어 · 90일 · 8개 매체</span><span class="tag">0–100 위험 지수</span><span class="tag">직접 판정 / 모델 예측 구분</span><p class="stamp">발행 당시 서술 기준 · 개인의 실시간 위험이나 발생 확률이 아님</p></header><main>
<div class="metrics"><div class="card"><div class="muted">평가한 실제 기사</div><div class="metric" id="total"></div></div><div class="card"><div class="muted">직접 AI 판정</div><div class="metric" id="direct"></div></div><div class="card"><div class="muted">개선 회차</div><div class="metric" id="rounds"></div></div><div class="card"><div class="muted">추가 AI 검토 후보</div><div class="metric" id="pending"></div></div></div>
<p class="note" id="quality-note"></p><section><h2>높은 부정성, 높은 위험성은 다릅니다.</h2><p>이미 끝난 사망·범죄는 부정성이 높아도 잔존 위험이 낮을 수 있습니다. 진행 중인 감염 확산·구조 위기는 추가 위해가 남습니다. N(부정성)과 A(서술의 정서적 강도)는 위험 지수에 더하지 않습니다.</p><img class="chart" src="figures/risk_distribution.png" alt="위험 지수 분포와 부정성 대비 잔존 위협의 관계"><details><summary>계산식과 해석</summary><p>R = 100 × S/4 × L/4 × (0.5 + 0.5×I/4) × (0.8 + 0.2×X/4). S는 심각도, L은 잔존 위해 근거, I는 시간적 임박성, X는 영향 범위입니다. L=0이면 잔존 위험은 0입니다. 각 축은 서열 점수이며 L을 발생 확률로 읽으면 안 됩니다. 구간 경계와 가중치는 연구 설계 선택입니다.</p></details></section>
<section><div class="row"><h2>기사별 위험 평가</h2><b id="count"></b></div><p class="muted">기사 제목을 누르면 축별 점수와 판정 근거, 모델의 불안정성을 볼 수 있습니다.</p><div class="controls"><input id="search" type="search" placeholder="제목·직접 판정 근거 검색" aria-label="검색"><select id="source" aria-label="매체"><option value="">모든 매체</option></select><select id="band" aria-label="위험 구간"><option value="">모든 위험 구간</option><option>critical</option><option>high</option><option>moderate</option><option>low</option><option>minimal</option></select><select id="review" aria-label="판정 유형"><option value="">모든 판정</option><option value="direct">직접 AI 판정</option><option value="model">모델 예측</option><option value="pending">추가 AI 검토 후보</option><option value="eligible">연구용 포함</option><option value="excluded">연구용 제외</option></select><select id="sort" aria-label="정렬"><option value="risk">위험 높은 순</option><option value="recent">발행 최신 순</option><option value="uncertain">모델 불안정성 순</option></select></div><div class="table-wrap"><table><thead><tr><th>기사 / 매체</th><th>위험 지수</th><th>N / T / A</th><th>판정</th></tr></thead><tbody id="rows"></tbody></table></div><div class="row" style="margin-top:16px"><button id="prev">이전</button><span id="page"></span><button id="next">다음</button></div></section>
<section><h2>반복 학습과 고정 AI 감사</h2><p>48건의 감사 기사는 시간상 검증·테스트 구간에서 먼저 고정했습니다. 아래 오차는 직접 판정으로 교체하기 전 모델 출력으로 계산했으며, 감사 점수는 학습이나 회차 선택에 쓰지 않았습니다. 일부 같은 사건의 후속 보도가 포함됩니다.</p><img class="chart" src="figures/audit_rounds.png" alt="같은 세션의 AI 판정에 대한 회차별 오차 변화"><p class="note">감사 중 발견한 홍보 삽입물은 180건에 같은 HTML 제거 규칙을 적용했습니다. 학습 기사에는 영향이 없어 모델 가중치는 유지했습니다. 정제 과정 전체가 감사 자료와 완전히 분리된 검증은 아니며, 정제 전 봉인 예측도 별도로 보존합니다.</p><div class="table-wrap"><table class="audit"><thead><tr><th>회차</th><th>위험 지수 MAE /100</th><th>N 오차 /4</th><th>T 오차 /4</th><th>A 오차 /4</th></tr></thead><tbody id="audit"></tbody></table></div><p class="note">같은 세션 AI의 판정과 모델 사이의 일치도입니다. 독립 정답에 대한 정확도는 아니며, 수치가 회차마다 반드시 좋아지는 것은 아닙니다. 12개 재학습 모델의 범위는 민감도이며 신뢰구간이 아닙니다. 모든 기사에 개별 전문 정독 판정을 했다고 표시하지 않습니다.</p></section>
<section><h2>데이터와 판단 기록</h2><div class="downloads"><a href="news_risk_scores.csv">전체 점수 CSV</a><a href="news_risk_scores.parquet">전체 점수 Parquet</a><a href="decision_audit.csv">직접 AI 판단 원장</a><a href="frozen_ai_audit.json">고정 감사 결과</a><a href="../../../docs/risk-rubric-v3.md">평가 기준</a><a href="../../corpus/20261109_v2/report.html">수집·정제 보고서</a></div></section><footer>공개 자료에는 짧은 발췌·원문 주소·해시·파생 점수만 제공합니다. 원래 본문·모델 특징 캐시는 Git에서 제외합니다. 이 보고서는 뉴스 사실 검증이나 생물학적 반응의 증거가 아닙니다.</footer></main>
<dialog id="detail"><div class="row"><span class="eyebrow" style="color:#126b64">ARTICLE ASSESSMENT</span><button id="close">닫기</button></div><h2 id="dtitle" style="margin-top:20px"></h2><p id="dmeta" class="muted"></p><p id="dexcerpt"></p><div class="axes" id="axes"></div><p id="drationale"></p><p id="dsensitivity" class="note"></p><p id="dsource" class="muted"></p><a id="dlink" target="_blank" rel="noopener noreferrer">원문 기사 열기 ↗</a><details><summary>출처·해시·모델 연결</summary><small id="dprovenance" style="overflow-wrap:anywhere"></small></details></dialog>
<script type="application/json" id="payload">__PAYLOAD__</script><script>
const D=JSON.parse(document.getElementById('payload').textContent), $=id=>document.getElementById(id);let page=0,filtered=[];const labels={minimal:'매우 낮음',low:'낮음',moderate:'중간',high:'높음',critical:'매우 높음'};
$('quality-note').textContent='원래 정제 본문 중 '+D.summary.native_promotion_corrections+'건의 삽입 홍보문을 추가 제거했습니다. 연구용 포함은 '+D.summary.assessment_research_eligible_articles.toLocaleString()+'건이며, 길이 기준 미달 5건은 직접 AI 판정을 제공하되 연구용에서 제외했습니다.';$('total').textContent=D.summary.articles.toLocaleString();$('direct').textContent=D.summary.direct_session_judgments.toLocaleString();$('rounds').textContent=D.summary.scoring_rounds+'회';$('pending').textContent=D.summary.further_ai_review_candidates.toLocaleString();
[...new Set(D.articles.map(a=>a.source))].sort().forEach(source=>{const o=document.createElement('option');o.value=source;o.textContent=source;$('source').append(o)});
function openArticle(a){$('dtitle').textContent=a.title;$('dmeta').textContent=a.source+' · '+a.published_date+' · '+(a.session_reviewed?'직접 AI 판정':'의미 모델 예측');$('dexcerpt').textContent=a.summary;$('axes').replaceChildren();for(const [k,label] of [['danger_score','위험 지수'],['N','부정성 N'],['T','잔존 위협 T'],['A','정서적 강도 A'],['S','심각도 S'],['L','잔존 위해 근거 L'],['I','임박성 I'],['X','범위 X']]){const div=document.createElement('div');div.className='axis';div.textContent=label;const b=document.createElement('b');b.textContent=(k==='danger_score'?a[k]:a[k]*4).toFixed(1)+(k==='danger_score'?' /100':' /4');div.append(b);$('axes').append(div)}$('drationale').textContent=a.rationale;$('dsensitivity').textContent='순수 모델 지수 '+a.model_danger_score.toFixed(1)+' · 재학습 민감도 '+a.bootstrap_p10.toFixed(1)+'–'+a.bootstrap_p90.toFixed(1)+' · 계산식 가중치 민감도 '+a.rubric_sensitivity_min.toFixed(1)+'–'+a.rubric_sensitivity_max.toFixed(1)+' (보장된 신뢰구간 아님)';$('dsource').textContent='상태: '+a.decision_state+' · '+(a.requires_further_ai_review?'추가 AI 검토 후보':'현재 추가 검토 표지 없음')+' · '+(a.assessment_research_eligible?'연구용 포함':'연구용 제외')+' · 발행 당시 서술 기준';$('dlink').href=/^https?:\/\//.test(a.url)?a.url:'#';$('dprovenance').textContent='ID '+a.news_id+' / 본문 SHA256 '+a.body_sha256+' / 평가 본문 SHA256 '+a.assessment_body_sha256+' / 본문 보정 '+a.input_correction+' / 시간 분할 '+a.split+' / 가장 가까운 개발 제목 '+a.nearest_development_news_id+' (의미 유사도 '+a.nearest_title_similarity.toFixed(3)+', 정답 일치 보장 아님)';$('detail').showModal()}
function render(){const q=$('search').value.toLowerCase(),s=$('source').value,b=$('band').value,r=$('review').value;filtered=D.articles.filter(a=>(!s||a.source===s)&&(!b||a.danger_band===b)&&(!q||(a.title+' '+a.rationale).toLowerCase().includes(q))&&(!r||(r==='direct'&&a.session_reviewed)||(r==='model'&&!a.session_reviewed)||(r==='pending'&&a.requires_further_ai_review)||(r==='eligible'&&a.assessment_research_eligible)||(r==='excluded'&&!a.assessment_research_eligible)));const sort=$('sort').value;filtered.sort((a,b)=>sort==='recent'?b.published_date.localeCompare(a.published_date):sort==='uncertain'?(b.bootstrap_p90-b.bootstrap_p10)-(a.bootstrap_p90-a.bootstrap_p10):b.danger_score-a.danger_score);page=Math.min(page,Math.max(0,Math.ceil(filtered.length/40)-1));$('count').textContent=filtered.length.toLocaleString()+'건';$('rows').replaceChildren();for(const a of filtered.slice(page*40,(page+1)*40)){const tr=document.createElement('tr'),td=document.createElement('td'),button=document.createElement('button');button.textContent=a.title;button.onclick=()=>openArticle(a);td.append(button,document.createElement('br'));const meta=document.createElement('small');meta.textContent=a.source+' · '+a.published_date.slice(0,10);td.append(meta);tr.append(td);const risk=document.createElement('td'),score=document.createElement('div');score.className='score';score.textContent=a.danger_score.toFixed(1);const pill=document.createElement('span');pill.className='pill '+a.danger_band;pill.textContent=labels[a.danger_band];risk.append(score,pill);tr.append(risk);const nta=document.createElement('td');nta.textContent=[a.N,a.T,a.A].map(x=>(x*4).toFixed(1)).join(' / ');tr.append(nta);const kind=document.createElement('td');kind.textContent=a.session_reviewed?'직접 AI':'모델 예측';if(a.requires_further_ai_review)kind.append(document.createElement('br'),'추가 검토');tr.append(kind);$('rows').append(tr)}$('page').textContent=(page+1)+' / '+Math.max(1,Math.ceil(filtered.length/40));$('prev').disabled=page===0;$('next').disabled=(page+1)*40>=filtered.length}
for(const id of ['search','source','band','review','sort'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=0;render()});$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};$('close').onclick=()=>$('detail').close();
for(const [cohort,items] of [['고정 48건',D.audit.rounds],['목적 표본 16건',D.audit.targeted_challenge_rounds]])for(const a of items){const tr=document.createElement('tr');for(const value of [cohort+' · '+a.round+'회',a.danger_index_mae_0_to_100.toFixed(2),...['N','T','A'].map(k=>a.ordinal_mae_0_to_4[k].toFixed(2))]){const td=document.createElement('td');td.textContent=value;tr.append(td)}$('audit').append(tr)}render();
</script></html>'''
    (out / "report.html").write_text(html.replace("__PAYLOAD__", payload), encoding="utf-8")
    return out / "report.html"
